CREATE TABLE arson_month (
    arson_month_id bigint NOT NULL,
    agency_id bigint NOT NULL,
    data_year smallint NOT NULL,
    month_num smallint NOT NULL,
    data_home character(1) DEFAULT 'T'::bpchar NOT NULL,
