--
-- Name: ct_counts; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW ct_counts AS
 SELECT count(temp.incident_id) AS count,
    sum(temp.stolen_value) AS stolen_value,
    sum(temp.recovered_value) AS recovered_value,
    temp.year,
    temp.ori,
    temp.state_id,
    temp.location_name,
    temp.offense_name,
    temp.victim_type_name,
    temp.prop_desc_name
   FROM ( SELECT DISTINCT ct_incident.incident_id,
            ref_agency.ori,
            ref_agency.state_id,
            nibrs_location_type.location_name,
            nibrs_offense_type.offense_name,
            nibrs_victim_type.victim_type_name,
            (ct_property.stolen_value)::numeric AS stolen_value,
            (ct_property.recovered_value)::numeric AS recovered_value,
            nibrs_prop_desc_type.prop_desc_name,
            date_part('year'::text, ct_incident.incident_date) AS year
           FROM ((((((((ct_incident
             LEFT JOIN ct_offense ON ((ct_incident.incident_id = ct_offense.incident_id)))
             LEFT JOIN nibrs_offense_type ON ((ct_offense.offense_type_id = nibrs_offense_type.offense_type_id)))
             LEFT JOIN nibrs_location_type ON ((ct_offense.location_id = nibrs_location_type.location_id)))
             LEFT JOIN ct_victim ON ((ct_victim.incident_id = ct_incident.incident_id)))
             LEFT JOIN nibrs_victim_type ON ((ct_victim.victim_type_id = nibrs_victim_type.victim_type_id)))
             LEFT JOIN ct_property ON ((ct_incident.incident_id = ct_property.incident_id)))
             LEFT JOIN nibrs_prop_desc_type ON ((nibrs_prop_desc_type.prop_desc_id = ct_property.prop_desc_id)))
             LEFT JOIN ref_agency ON ((ref_agency.agency_id = ct_incident.agency_id)))) temp
  GROUP BY GROUPING SETS ((temp.year, temp.prop_desc_name), (temp.year, temp.location_name), (temp.year, temp.victim_type_name), (temp.year, temp.offense_name), (temp.year, temp.state_id, temp.prop_desc_name), (temp.year, temp.state_id, temp.location_name), (temp.year, temp.state_id, temp.victim_type_name), (temp.year, temp.state_id, temp.offense_name), (temp.year, temp.ori, temp.prop_desc_name), (temp.year, temp.ori, temp.location_name), (temp.year, temp.ori, temp.victim_type_name), (temp.year, temp.ori, temp.offense_name))
  WITH NO DATA;


--
-- Name: ct_counts_ori; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW ct_counts_ori AS
 SELECT count(temp.incident_id) AS count,
    sum(temp.stolen_value) AS stolen_value,
    sum(temp.recovered_value) AS recovered_value,
    temp.year,
    temp.ori,
    temp.location_name,
    temp.offense_name,
    temp.victim_type_name,
    temp.prop_desc_name
   FROM ( SELECT DISTINCT ct_incident.incident_id,
            ref_agency.ori,
            nibrs_location_type.location_name,
            nibrs_offense_type.offense_name,
            nibrs_victim_type.victim_type_name,
            (ct_property.stolen_value)::numeric AS stolen_value,
            (ct_property.recovered_value)::numeric AS recovered_value,
            nibrs_prop_desc_type.prop_desc_name,
            date_part('year'::text, ct_incident.incident_date) AS year
           FROM ((((((((ct_incident
             LEFT JOIN ct_offense ON ((ct_incident.incident_id = ct_offense.incident_id)))
             LEFT JOIN nibrs_offense_type ON ((ct_offense.offense_type_id = nibrs_offense_type.offense_type_id)))
             LEFT JOIN nibrs_location_type ON ((ct_offense.location_id = nibrs_location_type.location_id)))
             LEFT JOIN ct_victim ON ((ct_victim.incident_id = ct_incident.incident_id)))
             LEFT JOIN nibrs_victim_type ON ((ct_victim.victim_type_id = nibrs_victim_type.victim_type_id)))
             LEFT JOIN ct_property ON ((ct_incident.incident_id = ct_property.incident_id)))
             LEFT JOIN nibrs_prop_desc_type ON ((nibrs_prop_desc_type.prop_desc_id = ct_property.prop_desc_id)))
             LEFT JOIN ref_agency ON ((ref_agency.agency_id = ct_incident.agency_id)))) temp
  GROUP BY GROUPING SETS ((temp.year, temp.ori, temp.prop_desc_name), (temp.year, temp.ori, temp.location_name), (temp.year, temp.ori, temp.victim_type_name), (temp.year, temp.ori, temp.offense_name))
  WITH NO DATA;


--
-- Name: ct_counts_states; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW ct_counts_states AS
 SELECT count(temp.incident_id) AS count,
    sum(temp.stolen_value) AS stolen_value,
    sum(temp.recovered_value) AS recovered_value,
    temp.year,
    temp.state_id,
    temp.location_name,
    temp.offense_name,
    temp.victim_type_name,
    temp.prop_desc_name
   FROM ( SELECT DISTINCT ct_incident.incident_id,
            ref_agency.state_id,
            nibrs_location_type.location_name,
            nibrs_offense_type.offense_name,
            nibrs_victim_type.victim_type_name,
            (ct_property.stolen_value)::numeric AS stolen_value,
            (ct_property.recovered_value)::numeric AS recovered_value,
            nibrs_prop_desc_type.prop_desc_name,
            date_part('year'::text, ct_incident.incident_date) AS year
           FROM ((((((((ct_incident
             LEFT JOIN ct_offense ON ((ct_incident.incident_id = ct_offense.incident_id)))
             LEFT JOIN nibrs_offense_type ON ((ct_offense.offense_type_id = nibrs_offense_type.offense_type_id)))
             LEFT JOIN nibrs_location_type ON ((ct_offense.location_id = nibrs_location_type.location_id)))
             LEFT JOIN ct_victim ON ((ct_victim.incident_id = ct_incident.incident_id)))
             LEFT JOIN nibrs_victim_type ON ((ct_victim.victim_type_id = nibrs_victim_type.victim_type_id)))
             LEFT JOIN ct_property ON ((ct_incident.incident_id = ct_property.incident_id)))
             LEFT JOIN nibrs_prop_desc_type ON ((nibrs_prop_desc_type.prop_desc_id = ct_property.prop_desc_id)))
             LEFT JOIN ref_agency ON ((ref_agency.agency_id = ct_incident.agency_id)))) temp
  GROUP BY GROUPING SETS ((temp.year, temp.prop_desc_name), (temp.year, temp.location_name), (temp.year, temp.victim_type_name), (temp.year, temp.offense_name), (temp.year, temp.state_id, temp.prop_desc_name), (temp.year, temp.state_id, temp.location_name), (temp.year, temp.state_id, temp.victim_type_name), (temp.year, temp.state_id, temp.offense_name))
  WITH NO DATA;


