--
-- Name: hc_counts; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW hc_counts AS
 SELECT count(temp.incident_id) AS count,
    temp.ori,
    temp.bias_name,
    temp.year,
    temp.state_id
   FROM ( SELECT DISTINCT hc_incident.incident_id,
            ref_agency.ori,
            nibrs_bias_list.bias_name,
            ref_agency.state_id,
            date_part('year'::text, hc_incident.incident_date) AS year
           FROM (((((hc_incident
             LEFT JOIN hc_offense ON ((hc_incident.incident_id = hc_offense.incident_id)))
             LEFT JOIN hc_bias_motivation ON ((hc_offense.offense_id = hc_bias_motivation.offense_id)))
             LEFT JOIN nibrs_offense_type ON ((nibrs_offense_type.offense_type_id = hc_offense.offense_type_id)))
             LEFT JOIN nibrs_bias_list ON ((nibrs_bias_list.bias_id = hc_bias_motivation.bias_id)))
             LEFT JOIN ref_agency ON ((ref_agency.agency_id = hc_incident.agency_id)))) temp
  GROUP BY GROUPING SETS ((temp.year, temp.bias_name), (temp.year, temp.state_id, temp.bias_name), (temp.year, temp.ori, temp.bias_name))
  WITH NO DATA;


--
-- Name: hc_counts_ori; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW hc_counts_ori AS
 SELECT count(temp.incident_id) AS count,
    temp.ori,
    temp.bias_name,
    temp.year
   FROM ( SELECT DISTINCT hc_incident.incident_id,
            ref_agency.ori,
            nibrs_bias_list.bias_name,
            date_part('year'::text, hc_incident.incident_date) AS year
           FROM (((((hc_incident
             LEFT JOIN hc_offense ON ((hc_incident.incident_id = hc_offense.incident_id)))
             LEFT JOIN hc_bias_motivation ON ((hc_offense.offense_id = hc_bias_motivation.offense_id)))
             LEFT JOIN nibrs_offense_type ON ((nibrs_offense_type.offense_type_id = hc_offense.offense_type_id)))
             LEFT JOIN nibrs_bias_list ON ((nibrs_bias_list.bias_id = hc_bias_motivation.bias_id)))
             LEFT JOIN ref_agency ON ((ref_agency.agency_id = hc_incident.agency_id)))) temp
  GROUP BY temp.year, temp.ori, temp.bias_name
  WITH NO DATA;


--
-- Name: hc_counts_states; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW hc_counts_states AS
 SELECT count(temp.incident_id) AS count,
    temp.bias_name,
    temp.year,
    temp.state_id
   FROM ( SELECT DISTINCT hc_incident.incident_id,
            nibrs_bias_list.bias_name,
            ref_agency.state_id,
            date_part('year'::text, hc_incident.incident_date) AS year
           FROM (((((hc_incident
             LEFT JOIN hc_offense ON ((hc_incident.incident_id = hc_offense.incident_id)))
             LEFT JOIN hc_bias_motivation ON ((hc_offense.offense_id = hc_bias_motivation.offense_id)))
             LEFT JOIN nibrs_offense_type ON ((nibrs_offense_type.offense_type_id = hc_offense.offense_type_id)))
             LEFT JOIN nibrs_bias_list ON ((nibrs_bias_list.bias_id = hc_bias_motivation.bias_id)))
             LEFT JOIN ref_agency ON ((ref_agency.agency_id = hc_incident.agency_id)))) temp
  GROUP BY GROUPING SETS ((temp.year, temp.bias_name), (temp.year, temp.state_id, temp.bias_name))
  WITH NO DATA;


