--
-- Name: victim_counts_2014; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW victim_counts_2014 AS
 SELECT count(temp.victim_id) AS count,
    temp.ori,
    temp.resident_status_code,
    temp.offender_relationship,
    temp.circumstance_name,
    temp.ethnicity,
    temp.offense_name,
    temp.state_id,
    temp.race_code,
    temp.age_num,
    temp.sex_code,
    temp.location_name,
    temp.prop_desc_name
   FROM ( SELECT DISTINCT nibrs_victim_denorm_2014.victim_id,
            ref_agency.ori,
            nibrs_victim_denorm_2014.ethnicity,
            nibrs_victim_denorm_2014.age_num,
            nibrs_victim_denorm_2014.race_code,
            nibrs_victim_denorm_2014.year,
            nibrs_victim_denorm_2014.resident_status_code,
            nibrs_victim_denorm_2014.offender_relationship,
            nibrs_victim_denorm_2014.circumstance_name,
            nibrs_victim_denorm_2014.offense_name,
            nibrs_victim_denorm_2014.sex_code,
            nibrs_victim_denorm_2014.state_id,
            nibrs_victim_denorm_2014.location_name,
            nibrs_victim_denorm_2014.prop_desc_name
           FROM (nibrs_victim_denorm_2014
             JOIN ref_agency ON ((ref_agency.agency_id = nibrs_victim_denorm_2014.agency_id)))
          WHERE (((nibrs_victim_denorm_2014.year)::integer = 2014) AND (nibrs_victim_denorm_2014.state_id IS NOT NULL))) temp
  GROUP BY GROUPING SETS ((temp.year, temp.race_code), (temp.year, temp.sex_code), (temp.year, temp.age_num), (temp.year, temp.location_name), (temp.year, temp.offense_name), (temp.year, temp.prop_desc_name), (temp.year, temp.resident_status_code), (temp.year, temp.offender_relationship), (temp.year, temp.circumstance_name), (temp.year, temp.ethnicity), (temp.year, temp.state_id, temp.race_code), (temp.year, temp.state_id, temp.sex_code), (temp.year, temp.state_id, temp.age_num), (temp.year, temp.state_id, temp.location_name), (temp.year, temp.state_id, temp.offense_name), (temp.year, temp.state_id, temp.prop_desc_name), (temp.year, temp.state_id, temp.resident_status_code), (temp.year, temp.state_id, temp.offender_relationship), (temp.year, temp.state_id, temp.circumstance_name), (temp.year, temp.state_id, temp.ethnicity), (temp.year, temp.ori, temp.race_code), (temp.year, temp.ori, temp.sex_code), (temp.year, temp.ori, temp.age_num), (temp.year, temp.ori, temp.location_name), (temp.year, temp.ori, temp.offense_name), (temp.year, temp.ori, temp.prop_desc_name), (temp.year, temp.ori, temp.resident_status_code), (temp.year, temp.ori, temp.offender_relationship), (temp.year, temp.ori, temp.circumstance_name), (temp.year, temp.ori, temp.ethnicity))
  WITH NO DATA;


