    bias_name text,
    attempt_complete_flag character varying(1),
    suspected_using text
);


--
-- Name: nibrs_offense_denorm_2014; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE nibrs_offense_denorm_2014 (
    CONSTRAINT nibrs_offense_denorm_2014_year_check CHECK (((year)::text = '2014'::text))
)
INHERITS (nibrs_offense_denorm);


--
-- Name: offense_counts_2014; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW offense_counts_2014 AS
 SELECT count(temp.offense_id) AS count,
    temp.ori,
    temp.offense_name,
    temp.weapon_name,
    temp.method_entry_code,
    temp.num_premises_entered,
    temp.location_name,
    temp.state_id
   FROM ( SELECT DISTINCT nibrs_offense_denorm_2014.offense_id,
            ref_agency.ori,
            nibrs_offense_denorm_2014.offense_name,
            nibrs_offense_denorm_2014.weapon_name,
            nibrs_offense_denorm_2014.method_entry_code,
            nibrs_offense_denorm_2014.num_premises_entered,
            nibrs_offense_denorm_2014.location_name,
            nibrs_offense_denorm_2014.state_id,
            nibrs_offense_denorm_2014.year
           FROM (nibrs_offense_denorm_2014
             JOIN ref_agency ON ((ref_agency.agency_id = nibrs_offense_denorm_2014.agency_id)))
          WHERE ((nibrs_offense_denorm_2014.year)::integer = 2014)) temp
  GROUP BY GROUPING SETS ((temp.year, temp.offense_name), (temp.year, temp.weapon_name), (temp.year, temp.method_entry_code), (temp.year, temp.num_premises_entered), (temp.year, temp.location_name), (temp.year, temp.state_id, temp.offense_name), (temp.year, temp.state_id, temp.weapon_name), (temp.year, temp.state_id, temp.method_entry_code), (temp.year, temp.state_id, temp.num_premises_entered), (temp.year, temp.state_id, temp.location_name), (temp.year, temp.ori, temp.offense_name), (temp.year, temp.ori, temp.weapon_name), (temp.year, temp.ori, temp.method_entry_code), (temp.year, temp.ori, temp.num_premises_entered), (temp.year, temp.ori, temp.location_name))
  WITH NO DATA;


--
-- Name: nibrs_method_entry_code; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW nibrs_method_entry_code AS
 SELECT DISTINCT offense_counts_2014.method_entry_code
   FROM offense_counts_2014
  WITH NO DATA;


