CREATE MATERIALIZED VIEW offender_counts_1991 AS
 SELECT count(temp.offender_id) AS count,
    temp.ethnicity,
    temp.prop_desc_name,
    temp.offense_name,
    temp.state_id,
    temp.race_code,
    temp.location_name,
    temp.age_num,
    temp.sex_code,
    temp.ori
   FROM ( SELECT DISTINCT nibrs_offender_denorm_1991.offender_id,
            nibrs_offender_denorm_1991.ethnicity,
            nibrs_offender_denorm_1991.age_code,
            nibrs_offender_denorm_1991.age_num,
            nibrs_offender_denorm_1991.race_code,
