--

CREATE TABLE offense_classification (
    classification_id smallint NOT NULL,
    classification_name character varying(50),
    class_sort_order smallint
);


--
-- Name: offense_counts_1991; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW offense_counts_1991 AS
 SELECT count(temp.offense_id) AS count,
    temp.ori,
    temp.offense_name,
    temp.weapon_name,
    temp.method_entry_code,
    temp.num_premises_entered,
    temp.location_name,
    temp.state_id
   FROM ( SELECT DISTINCT nibrs_offense_denorm_1991.offense_id,
            ref_agency.ori,
            nibrs_offense_denorm_1991.offense_name,
            nibrs_offense_denorm_1991.weapon_name,
            nibrs_offense_denorm_1991.method_entry_code,
            nibrs_offense_denorm_1991.num_premises_entered,
            nibrs_offense_denorm_1991.location_name,
            nibrs_offense_denorm_1991.state_id,
            nibrs_offense_denorm_1991.year
           FROM (nibrs_offense_denorm_1991
             JOIN ref_agency ON ((ref_agency.agency_id = nibrs_offense_denorm_1991.agency_id)))
          WHERE ((nibrs_offense_denorm_1991.year)::integer = 1991)) temp
  GROUP BY GROUPING SETS ((temp.year, temp.offense_name), (temp.year, temp.weapon_name), (temp.year, temp.method_entry_code), (temp.year, temp.num_premises_entered), (temp.year, temp.location_name), (temp.year, temp.state_id, temp.offense_name), (temp.year, temp.state_id, temp.weapon_name), (temp.year, temp.state_id, temp.method_entry_code), (temp.year, temp.state_id, temp.num_premises_entered), (temp.year, temp.state_id, temp.location_name), (temp.year, temp.ori, temp.offense_name), (temp.year, temp.ori, temp.weapon_name), (temp.year, temp.ori, temp.method_entry_code), (temp.year, temp.ori, temp.num_premises_entered), (temp.year, temp.ori, temp.location_name))
  WITH NO DATA;


