-- Name: participation_rates; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE participation_rates (
    participation_id integer NOT NULL,
    year smallint NOT NULL,
    state_id bigint,
    state_name character varying(255),
    county_id bigint,
    county_name character varying(255),
    total_agencies integer,
    participating_agencies integer,
    participation_rate double precision,
    nibrs_participating_agencies integer,
    nibrs_participation_rate double precision,
    covered_agencies integer,
    covered_rate double precision,
    total_population bigint,
    participating_population bigint,
    nibrs_participating_population bigint
);


