--
-- Name: victim_counts_1991; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW victim_counts_1991 AS
 SELECT count(temp.victim_id) AS count,
    temp.ori,
    temp.resident_status_code,
    temp.offender_relationship,
    temp.circumstance_name,
    temp.ethnicity,
    temp.offense_name,
    temp.state_id,
    temp.race_code,
    temp.age_num,
    temp.sex_code,
    temp.location_name,
    temp.prop_desc_name
   FROM ( SELECT DISTINCT nibrs_victim_denorm_1991.victim_id,
            ref_agency.ori,
            nibrs_victim_denorm_1991.ethnicity,
            nibrs_victim_denorm_1991.age_num,
            nibrs_victim_denorm_1991.race_code,
